function markdownHeading(level, title) {
  const lv = Math.max(1, Math.min(6, Number(level) || 2));
  return `${'#'.repeat(lv)} ${title}`;
}

function markdownIsBlank(value) {
  if (value == null) return true;
  if (Array.isArray(value)) return value.length === 0;
  if (typeof value === 'object') return Object.keys(value).length === 0;
  return String(value).trim() === '';
}

function markdownFieldConfig(field) {
  if (typeof field === 'string') return { field };
  return field ?? {};
}

function markdownLookupField(fieldName) {
  const gd = gridDef();
  const hd = headerDef();
  return (gd?.fields ?? []).find(f => f.field === fieldName) ||
         (hd?.fields ?? []).find(f => f.field === fieldName) ||
         null;
}

function markdownLabelForField(fieldCfg) {
  const cfg = markdownFieldConfig(fieldCfg);
  const def = markdownLookupField(cfg.field);
  return cfg.caption || cfg.label || def?.caption || cfg.field || '';
}

function markdownFormatDataValue(value, fieldCfg=null) {
  const cfg = markdownFieldConfig(fieldCfg);
  const def = markdownLookupField(cfg.field);
  if (value == null) return '';
  if (Array.isArray(value) || (typeof value === 'object' && value !== null)) {
    return JSON.stringify(value, null, 2);
  }
  return formatValue(value, def || cfg);
}

function markdownBlockquote(value) {
  return String(value ?? '')
    .split(/\r?\n/)
    .map(line => `> ${line}`)
    .join('\n');
}

function markdownApplyTemplate(template, row, index=0) {
  return String(template ?? '')
    .replace(/\{#\}/g, String(index + 1))
    .replace(/\{index\}/g, String(index))
    .replace(/\{no\}/g, String(row?.no ?? index + 1))
    .replace(/\{([^}]+)\}/g, (_, path) => {
      const value = getByPath(row, path.trim());
      return value == null ? '' : String(value);
    })
    .replace(/\s+/g, ' ')
    .trim();
}

function pushGenericMarkdownField(lines, obj, fieldCfg, level=3) {
  const cfg = markdownFieldConfig(fieldCfg);
  if (!cfg.field) return;
  const value = getByPath(obj, cfg.field);
  if (cfg.visible === false) return;
  if (markdownIsBlank(value) && cfg.showEmpty !== true) return;

  const label = markdownLabelForField(cfg);
  const format = cfg.format || cfg.markdownFormat || 'auto';

  if (format === 'heading') {
    lines.push(markdownHeading(level, markdownFormatDataValue(value, cfg)));
    return;
  }

  if (format === 'blockquote') {
    lines.push(`\n${markdownHeading(level, label)}`);
    lines.push('');
    lines.push(markdownBlockquote(markdownFormatDataValue(value, cfg)));
    return;
  }

  if (format === 'paragraph' || format === 'textarea' || String(value).includes('\n')) {
    lines.push(`\n${markdownHeading(level, label)}`);
    lines.push('');
    lines.push(markdownFormatDataValue(value, cfg));
    return;
  }

  if (Array.isArray(value) || (typeof value === 'object' && value !== null)) {
    lines.push(`- ${label}:`);
    lines.push(markdownValueBlock(value));
    return;
  }

  lines.push(`- ${label}: ${markdownEscape(markdownFormatDataValue(value, cfg))}`);
}

function markdownObjectTable(items, fields) {
  const list = Array.isArray(items) ? items : [];
  const fieldCfgs = (fields ?? []).map(markdownFieldConfig).filter(f => f.field);
  if (!fieldCfgs.length) return '';
  const head = '| ' + fieldCfgs.map(f => markdownEscape(markdownLabelForField(f))).join(' | ') + ' |';
  const sep = '| ' + fieldCfgs.map(() => '---').join(' | ') + ' |';
  const body = list.map(item => '| ' + fieldCfgs.map(f => markdownEscape(markdownFormatDataValue(getByPath(item, f.field), f))).join(' | ') + ' |');
  return [head, sep, ...body].join('\n');
}

function renderMarkdownArray(lines, arrayValue, section, level=3) {
  const items = Array.isArray(arrayValue) ? arrayValue : [];
  if (!items.length) {
    if (section.showEmpty === true) lines.push('（なし）');
    return;
  }

  const format = section.format || 'table';
  const fields = section.fields ?? [];

  if (format === 'constraintList' || format === 'detailList') {
    items.forEach((item, index) => {
      const titleTpl = section.itemTitle || (format === 'constraintList' ? '{id}：{title}' : '{#}. {title}');
      const title = markdownApplyTemplate(titleTpl, item, index) || `${index + 1}`;
      lines.push(`\n${markdownHeading(level, title)}`);
      const fieldCfgs = fields.map(markdownFieldConfig).filter(f => f.field);
      if (fieldCfgs.length) {
        fieldCfgs.forEach(f => pushGenericMarkdownField(lines, item, f, level + 1));
      } else {
        lines.push(markdownValueBlock(item));
      }
    });
    return;
  }

  if (format === 'json') {
    lines.push(markdownValueBlock(items));
    return;
  }

  const table = markdownObjectTable(items, fields);
  if (table) lines.push(table);
  else lines.push(markdownValueBlock(items));
}

function renderGenericMarkdownSection(lines, section, context={ data: sourceData, rows: currentRows }, level=2) {
  if (!section || section.visible === false) return;
  const title = section.title || section.caption;
  if (title) {
    lines.push(`\n${markdownHeading(level, title)}`);
    lines.push('');
  }

  const source = section.source || 'root';
  if (source === 'rows' || source === 'currentRows' || source === 'grid') {
    const rows = Array.isArray(context.rows) ? context.rows : [];
    if (section.format === 'table') {
      lines.push(markdownObjectTable(rows, section.fields ?? []));
      return;
    }

    rows.forEach((row, index) => {
      const itemTitle = markdownApplyTemplate(section.itemTitle || '{no}. {group_id}：{title}', row, index) || `${index + 1}`;
      lines.push(`\n${markdownHeading(level + 1, itemTitle)}`);
      (section.fields ?? []).forEach(f => pushGenericMarkdownField(lines, row, f, level + 2));
      (section.sections ?? []).forEach(child => renderGenericMarkdownSection(lines, child, { data: row, rows: context.rows }, level + 2));
    });
    return;
  }

  const obj = context.data ?? sourceData;

  if (section.arrayField) {
    const arrayValue = getByPath(obj, section.arrayField);
    renderMarkdownArray(lines, arrayValue, section, level + 1);
    return;
  }

  (section.fields ?? []).forEach(f => pushGenericMarkdownField(lines, obj, f, level + 1));
  (section.sections ?? []).forEach(child => renderGenericMarkdownSection(lines, child, { data: obj, rows: context.rows }, level + 1));
}

function buildGenericSectionsMarkdown() {
  applyHeaderEdits();
  const cfg = markdownConfig();
  const gd = gridDef();
  const rows = Array.isArray(currentRows) ? currentRows : [];
  const title = cfg.title || sourceData?.title || mainView()?.caption || gd?.caption || 'JSON Object Studio Export';
  const lines = [];

  lines.push(`# ${title}`);
  lines.push('');
  lines.push(`- 出力日時: ${new Date().toLocaleString('ja-JP')}`);
  if (sourceData?.target) lines.push(`- 対象: ${sourceData.target}`);
  if (sourceData?.schema_version) lines.push(`- schema_version: ${sourceData.schema_version}`);
  if (sourceData?.status) lines.push(`- status: ${sourceData.status}`);
  lines.push(`- 件数: ${rows.length}`);

  const sections = Array.isArray(cfg.sections) ? cfg.sections : [];
  if (!sections.length) return buildGenericMarkdown();

  sections.forEach(section => renderGenericMarkdownSection(lines, section, { data: sourceData, rows }, 2));
  return lines.join('\n').replace(/\n{4,}/g, '\n\n\n');
}


function markdownAiPromptConfigs() {
  const configs = [];
  const pushPrompt = (prompt, sourceSection=null, sourceName='') => {
    if (!prompt) return;
    const list = Array.isArray(prompt) ? prompt : [prompt];
    list.forEach(item => {
      if (!item || item.enabled === false) return;
      configs.push({ ...item, _sourceSection: sourceSection, _sourceName: sourceName });
    });
  };

  pushPrompt(viewDef?.aiPrompt || viewDef?.ai_prompt || viewDef?.markdown?.aiPrompt || viewDef?.markdown?.ai_prompt, null, 'viewDef');
  const mv = mainView();
  pushPrompt(mv?.aiPrompt || mv?.ai_prompt || mv?.markdown?.aiPrompt || mv?.markdown?.ai_prompt, null, 'view');
  (mv?.sections ?? []).forEach(section => {
    pushPrompt(section?.aiPrompt || section?.ai_prompt || section?.markdown?.aiPrompt || section?.markdown?.ai_prompt, section, section?.id || section?.caption || 'section');
  });
  return configs;
}

function markdownRowsForAiPrompt(config={}) {
  const rowSource = String(config.rowSource ?? config.sourceRows ?? config.rows ?? 'filtered').toLowerCase();
  let rows;
  if (rowSource === 'all' || rowSource === 'current' || rowSource === 'currentrows') {
    rows = Array.isArray(currentRows) ? currentRows : [];
  } else if (rowSource === 'selected') {
    rows = selectedIndex >= 0 && Array.isArray(currentRows) && currentRows[selectedIndex] ? [currentRows[selectedIndex]] : [];
  } else {
    rows = Array.isArray(filteredRows) && filteredRows.length ? filteredRows.map(x => x.row) : (Array.isArray(currentRows) ? currentRows : []);
  }
  const maxRows = Number(config.maxRows ?? config.limit ?? 0);
  if (maxRows > 0) rows = rows.slice(0, maxRows);
  return rows;
}

function markdownFieldsForAiPrompt(config={}, sourceSection=null) {
  const gd = gridDef();
  let fields = Array.isArray(config.fields) && config.fields.length
    ? config.fields.map(markdownFieldConfig)
    : ((sourceSection?.fields ?? gd?.fields ?? []).map(markdownFieldConfig));
  const include = config.includeFields || config.include_fields;
  if (Array.isArray(include) && include.length) {
    const set = new Set(include.map(String));
    fields = fields.filter(f => set.has(String(f.field)));
  } else if (config.visibleOnly !== false) {
    fields = fields.filter(f => f.grid?.visible !== false && f.visible !== false);
  }
  const exclude = config.excludeFields || config.exclude_fields;
  if (Array.isArray(exclude) && exclude.length) {
    const set = new Set(exclude.map(String));
    fields = fields.filter(f => !set.has(String(f.field)));
  }
  return fields.filter(f => f.field);
}

function markdownTsvCell(value, field=null) {
  const text = formatValue(value, field)
    .replace(/\r?\n/g, '\\n')
    .replace(/\t/g, ' ');
  return text;
}

function markdownRowsToTsv(rows, fields) {
  const header = fields.map(f => markdownLabelForField(f)).join('\t');
  const body = rows.map(row => fields.map(f => markdownTsvCell(getByPath(row, f.field), f)).join('\t'));
  return [header, ...body].join('\n');
}

function markdownRowsToGridJson(rows, fields, config={}) {
  const columns = fields.map(f => ({
    field: f.field,
    caption: markdownLabelForField(f),
    type: f.type ?? null
  }));
  const rawRows = rows.map(row => {
    const out = {};
    fields.forEach(f => { out[f.field] = getByPath(row, f.field); });
    return out;
  });
  return {
    view_def: lastLoadedDefName || sourceData?.view_def || '',
    data_file: currentDataNameForExport() || '',
    section: config.sectionCaption || config._sourceSection?.caption || gridDef()?.caption || '',
    row_count: rawRows.length,
    columns,
    rows: rawRows
  };
}

function applyAiPromptTemplate(template, context) {
  return String(template ?? '').replace(/\{\{\s*([^}]+?)\s*\}\}/g, (_, key) => {
    const value = context[String(key).trim()];
    return value == null ? '' : String(value);
  });
}

function markdownAiPromptTemplate(config={}, context={}) {
  const tpl = config.template ?? config.prompt ?? [
    '以下は {{sectionCaption}} のTSVです。',
    'この内容をもとに、{{targetFile}} に追加する候補データを作成してください。',
    '',
    '条件:',
    '- 出力はJSON配列',
    '',
    'TSV:'
  ];
  const text = Array.isArray(tpl) ? tpl.join('\n') : String(tpl);
  return applyAiPromptTemplate(text, context).trimEnd();
}

function buildMarkdownAiCopyBlocks() {
  const configs = markdownAiPromptConfigs();
  if (!configs.length) return '';

  const blocks = [];
  configs.forEach((config, idx) => {
    const rows = markdownRowsForAiPrompt(config);
    const fields = markdownFieldsForAiPrompt(config, config._sourceSection);
    if (!fields.length) return;

    const sectionCaption = config.sectionCaption || config._sourceSection?.caption || gridDef()?.caption || 'Grid';
    const context = {
      targetFile: config.targetFile || sourceData?.targetFile || currentDataNameForExport() || '',
      sourceFile: currentDataNameForExport() || '',
      dataFile: currentDataNameForExport() || '',
      viewDef: lastLoadedDefName || sourceData?.view_def || '',
      title: config.title || sourceData?.title || mainView()?.caption || sectionCaption,
      sectionCaption,
      rowCount: rows.length,
      totalRowCount: Array.isArray(currentRows) ? currentRows.length : rows.length,
      filteredRowCount: Array.isArray(filteredRows) ? filteredRows.length : rows.length
    };

    const title = config.title || `AI貼り付け用プロンプト${configs.length > 1 ? ' ' + (idx + 1) : ''}`;
    const tsv = markdownRowsToTsv(rows, fields);
    const prompt = markdownAiPromptTemplate(config, context);
    const promptWithTsv = (prompt ? prompt + '\n' : '') + tsv;

    blocks.push(`## ${markdownEscape(title)}`);
    if (config.description) {
      blocks.push('');
      blocks.push(String(config.description));
    }
    blocks.push('');
    blocks.push('<details open>');
    blocks.push(`<summary>${markdownEscape(config.summary || 'プロンプト + TSV を表示')}</summary>`);
    blocks.push('');
    blocks.push('```text');
    blocks.push(promptWithTsv);
    blocks.push('```');
    blocks.push('');
    blocks.push('</details>');

    if (config.includeGridJson || config.includeJson || config.gridJson) {
      blocks.push('');
      blocks.push('<details>');
      blocks.push('<summary>Grid JSON を表示</summary>');
      blocks.push('');
      blocks.push('```json');
      blocks.push(JSON.stringify(markdownRowsToGridJson(rows, fields, { ...config, sectionCaption }), null, 2));
      blocks.push('```');
      blocks.push('');
      blocks.push('</details>');
    }
  });

  if (!blocks.length) return '';
  return ['---', '', '# AI貼り付け用', '', ...blocks].join('\n');
}

function appendMarkdownAiCopyBlocks(markdownText) {
  const block = buildMarkdownAiCopyBlocks();
  if (!block) return markdownText;
  return String(markdownText ?? '').replace(/\s+$/,'') + '\n\n' + block;
}

function buildMarkdownFromCurrentData() {
  applyHeaderEdits();
  const md = buildMarkdownByRegisteredType(markdownExportType());
  return appendMarkdownAiCopyBlocks(md);
}


// v0.5-registry: Markdown export builders.
registerMarkdownExportBuilder('auto', buildGenericMarkdown);
registerMarkdownExportBuilder('screen_state_expected', buildScreenStateExpectedMarkdown);
registerMarkdownExportBuilder('screen_state_diff', buildScreenStateDiffMarkdown);
registerMarkdownExportBuilder('screen_state_test_patterns', buildScreenStateTestPatternsMarkdown);
registerMarkdownExportBuilder('generic_sections', buildGenericSectionsMarkdown);

function downloadTextFile(filename, text, type='text/markdown') {
  const blob = new Blob([text], {type});
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = filename;
  a.click();
  URL.revokeObjectURL(a.href);
}

function normalizeMarkdownFileName(name) {
  let n = String(name || '').trim();
  if (!n) n = 'json_studio_export.md';
  n = n.replace(/[\\/:*?"<>|]/g, '_');
  if (!/\.(md|markdown)$/i.test(n)) n += '.md';
  return n;
}

function currentDataNameForExport() {
  const fromCombo = $('dataNameInput')?.value;
  if (fromCombo) return fromCombo.split('/').pop();
  const fromApi = currentDataApiUrl ? jsonNameFromUrl(currentDataApiUrl, 'data') : null;
  if (fromApi) return fromApi.split('/').pop();
  return null;
}

function markdownExportFileName() {
  const cfg = markdownConfig();
  const base =
    sourceData?.export_md_name ||
    sourceData?.markdown_file ||
    cfg.fileName ||
    cfg.filename ||
    cfg.defaultFileName ||
    sourceData?.title ||
    currentDataNameForExport() ||
    'json_studio_export';
  const clean = normalizeMarkdownFileName(String(base).replace(/\.json$/i, ''));
  return clean;
}

async function saveMarkdownToManagedFolder(filename, content) {
  const safeName = normalizeMarkdownFileName(filename);
  const res = await fetch(`/api/markdown/${encodeURIComponent(safeName)}`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ name: safeName, content })
  });
  if (!res.ok) throw new Error(await res.text());
  return safeName;
}

async function exportMarkdown() {
  if (!sourceData || !viewDef) {
    setStatus('Markdown出力するデータがありません');
    return;
  }
  const md = buildMarkdownFromCurrentData();
  const fileName = markdownExportFileName();
  try {
    const savedName = await saveMarkdownToManagedFolder(fileName, md);
    setStatus(`Markdownを data/markdown/${savedName} に出力しました`);
    location.href = `mdViewer.html?file=${encodeURIComponent(savedName)}`;
  } catch (err) {
    console.warn('管理Markdown保存に失敗。ダウンロードへフォールバックします。', err);
    downloadTextFile(fileName, md);
    setStatus('Markdown API保存に失敗したため、ダウンロード出力しました: ' + err.message);
  }
}
